// Real SQLite transactions with synthetic sessions, not login/SY evidence.
#define main retained_file_storage_main
#include "file_storage_tests.cpp"
#undef main
int main(int argc,char** argv){try{
    check(argc==2,"new retained fixture root required");const std::filesystem::path root=argv[1];check(!std::filesystem::exists(root),"prior fixtures preserved");
    sfx::test::FakeStoragePathPolicy paths;auto s=settings(root);storage::SqliteStorage db(s,paths);check(db.start().succeeded(),"current schema started");check(db.shutdown().succeeded(),"stopped for synthetic actors");seed(s.data_directory/"SFX.DB");check(db.start().succeeded(),"synthetic actors opened through managed storage");
    const auto policy=*db.security_policy().value;const app::MessageActor sysop{id(1),1,1,policy.revision},caller{id(2),2,1,policy.revision};const app::MessageConfigurationActor owner{true,{}};
    auto config=*db.ftn_configuration(owner).value;for(const auto* code:{"ONE","TWO"}){app::FtnNetwork n;n.code=code;n.name=std::string("Network ")+code;n.address=std::string(code)=="ONE"?"64202:100/1":"64203:100/1";n.enabled=true;config.networks.push_back(n);app::FtnLink l;l.network=code;l.code="PEER";l.name="Synthetic peer";l.address=std::string(code)=="ONE"?"64202:100/2":"64203:100/2";l.host="127.0.0.1";l.enabled=true;l.credentials.session={1};config.links.push_back(l);}
    check(bool(db.change_ftn_configuration(owner,id(100).bytes,config)),"two isolated synthetic networks published");config=*db.ftn_configuration(owner).value;
    unsigned sequence=110;for(const auto& network:config.networks){app::FtnIngressReceipt r;r.id=id(sequence++);r.session=id(sequence++);r.identity.fill(static_cast<std::uint8_t>(sequence));r.network=network.code;r.link="PEER";r.proof=app::FtnIngressProof::inbound_cram;r.configuration_revision=config.revision;r.file={network.code+".pkt",1,1700000000};check(bool(db.begin_ftn_ingress(owner,r)),"synthetic ingress begun");app::FtnDigest digest;digest.fill(17);check(bool(db.advance_ftn_ingress(owner,r.id,0,1,digest,app::FtnIngressState::received,{})),"synthetic ingress completed");check(bool(db.advance_ftn_ingress(owner,r.id,1,1,digest,app::FtnIngressState::held,"fixture_hold")),"synthetic ingress held");}
    for(const auto& network:config.networks){const auto q=db.sysop_ftn_queues(sysop,network.code,0);const auto h=db.sysop_ftn_held(sysop,network.code,{});check(q&&q.value&&q.value->rows.size()==1&&q.value->rows[0].network==network.code,"queue rows are network scoped");check(h&&h.value&&h.value->rows.size()==1&&h.value->rows[0].network==network.code,"held rows are network scoped");}
    check(!db.sysop_ftn_queues(caller,"ONE",0)&&!db.sysop_ftn_held(caller,"ONE",{}),"ordinary caller cannot inspect Sysop queues or held mail");auto forged=sysop;forged.session=caller.session;check(!db.sysop_ftn_queues(forged,"ONE",0),"cross-account session rejected");check(!db.sysop_ftn_queues(sysop,"MISSING",0),"removed network refused");
    app::SaveAccountRequest save;save.account_id=2;save.expected_revision=1;save.expected_policy_revision=policy.revision;save.display_name="Alice";save.security_level=10;save.purge_allowed=true;save.profile.location="Portland";save.audit={id(200),id(201),1,1792248000,app::AuditReasonCode::sysop_action,id(1)};
    const auto saved=db.save_account(save);check(saved.succeeded()&&db.find_account_by_id(2).value->profile.location=="Portland","live Sysop transaction saves selected account");save.expected_revision=*saved.revision;save.audit.event_id=id(202);save.audit.sysop_session=id(2);save.profile.location="Forbidden";check(!db.save_account(save)&&db.find_account_by_id(2).value->profile.location=="Portland","writer rejects cross-account proof before any change");
    check(db.finalize_session({id(1),0,1792248000,app::SessionOutcomeCode::normal,id(203)}).succeeded(),"end exact synthetic Sysop session");save.audit.sysop_session=id(1);save.audit.event_id=id(204);check(!db.save_account(save)&&!db.sysop_ftn_held(sysop,"ONE",{}),"ended Sysop session cannot mutate or read");
    save.audit.sysop_session.reset();save.audit.actor_account_id.reset();save.audit.event_id=id(205);check(db.save_account(save).succeeded(),"existing protected local editor semantics retained");check(db.shutdown().succeeded(),"fixture stopped with evidence retained");
    std::cout<<"PASS Sysop storage: "<<checks<<" checks\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL Sysop storage: "<<e.what()<<'\n';return 1;}}
